const capabilities=[['GTFSの作成・編集','便の追加・削除・時刻、停車列、路線名、停留所を編集・GTFS出力','主要項目の事前検査。GTFS-JP v4の全仕様適合認証、配車・労務計画は未実施'],['データ変換・統合表示','CSV列の対応付け、複数GTFSを名前空間で分離して同じ地図に表示','IC個票の匿名化・名寄せは対象外。統合GTFSへのID改番は未実装'],['運行頻度','指定日・方向・時間帯の便数／停留所出発数を比較','運行予定。実運行・遅延ではない'],['到達比較','待ち・通常乗降制限・最大2回乗換・直線徒歩・24時超を計算','歩行道路・勾配・車いす経路・帰路は未評価。頻度運行exact_times=0と予約型は除外'],['乗降・OD','観測日とID照合、区間車内人数、OD行列・地図','全停車観測と初期人数の確認が車内人数算定の条件。欠測は0にしない'],['需要予測・感度','時系列の過去検証、一定弾力性／線形感度、係数レンジ','係数は仮定。経路変更・新規路線・需要の因果効果は未推定'],['費用便益・収支','年別増分・台形近似・割引・更新・残存価値・NPV・感度・損益分岐','部分評価。道路配分・事故・CO2の自動推計、正式な事業採否は対象外'],['判断・学習','3案と現状維持、責任者・負担者・基準・実測計画、再計算ファイル','現地の合意・実証・政策判断は未実行']];
let state={schema:'oita-planning-project/1',engine:ENGINE_VERSION,name:'大分県・公共交通の改善検討',feeds:[],scenarios:[{id:'s1',name:'案1 接続時刻の調整',edits:[]},{id:'s2',name:'案2 便の追加・再配分',edits:[]},{id:'s3',name:'案3 停車列・経路の再設計',edits:[]}],selected:'s1',decision:{},observations:null,od:null,forecast:null,demand:null};
