let exampleFeed=null,exampleMap=null,exampleMarkers=null,exampleAdded=false;
let catalog=[],analysis=null,changed=[],reach=null,map,markers,shapeLayer,odLayer,mapMode='supply',loadedCSV=null,cashflowImport=null,rideResult=null,odResult=null,forecastResult=null,econResult=null,latestRevision=0,pending=new Map(),requestId=0;
let worker=new Worker(new URL('./worker.mjs',import.meta.url),{type:'module'});
worker.onmessage=({data})=>{const p=pending.get(data.id);if(!p)return;clearTimeout(p.timer);pending.delete(data.id);data.error?p.reject(Error(data.error)):p.resolve(data.result)};
worker.onerror=()=>{for(const p of pending.values()){clearTimeout(p.timer);p.reject(Error('分析処理を完了できませんでした。データ量を減らして再読み込みしてください'))}pending.clear()};
function request(type,payload){return new Promise((resolve,reject)=>{const id=++requestId,timer=setTimeout(()=>{pending.delete(id);reject(Error('分析に時間がかかっています。データを分けて再実行してください'))},120000);pending.set(id,{resolve,reject,timer});worker.postMessage({id,type,payload})})}
const scenario=()=>state.scenarios.find(s=>s.id===state.selected);
const currentFeed=()=>changed.find(f=>f.id===$('#edit-feed').value);
function message(text,busy=false){$('#status').textContent=text;$('#status').classList.toggle('busy',busy)}
function error(e){$('#error').textContent=e.message??String(e);$('#error').hidden=false;message('入力と条件をご確認ください')}
async function guarded(fn){$('#error').hidden=true;try{return await fn()}catch(e){error(e)}}
function on(id,event,fn){$(id).addEventListener(event,e=>guarded(()=>fn(e)))}
function route(){
  const view=location.hash.slice(1);if(view==='content')return;
  const page=view==='access'?'design':['example','design','observed','demand','economics','data','report'].includes(view)?view:'example';
  document.body.dataset.page=page;document.body.classList.toggle('access-mode',view==='access');
  $$('.page').forEach(p=>p.hidden=p.id!=='page-'+page);
  $$('#lab-nav a').forEach(a=>{const active=a.dataset.view===page;a.classList.toggle('active',active);active?a.setAttribute('aria-current','page'):a.removeAttribute('aria-current')});
  $('#page-design h1').textContent=view==='access'?'60分で、どこまで行ける？':'時刻や本数を変えたら、どうなる？';
  $('#page-design .page-heading p').textContent=view==='access'?'出発地と時刻を選ぶと、待ち時間や乗り継ぎを含めて行ける停留所がわかります。':'元の時刻表と、いま編集中の案を比較します。最初は同じなので、差はありません。';
  if(page==='design'&&map)setTimeout(()=>map.invalidateSize(),20);
  if(page==='example'&&exampleFeed)renderExample();
  if(page==='report')renderComparison();
  document.title=($('#page-'+page+' h1')?.textContent??'交通計画')+'｜大分 交通データ';
}
function renderExample(){
  if(!exampleFeed)return;
  const result=exampleComparison(exampleFeed,exampleAdded);
  $('#example-description').textContent=result.route+' ／ '+result.first+' → '+result.last;
  $('#example-time').textContent=result.time+'発';$('#example-new-time').textContent=result.newTime+'発';
  $('#example-add').disabled=exampleAdded;$('#example-add').textContent=exampleAdded?'1便追加しました':'1便増やして、結果を見る';$('#example-reset').hidden=!exampleAdded;
  $('#example-result').innerHTML=exampleAdded?`<strong>この路線は1日 ${fmt(result.before)}便 → ${fmt(result.after)}便に。</strong><p>${fmt(result.rows.filter(r=>r.after>r.before).length)}か所の乗り場で、利用できる便が増えました。</p>`:`<strong>変更前：この路線は1日 ${fmt(result.before)}便。</strong><p>「1便増やして、結果を見る」を押すと、変化がここに出ます。</p>`;
  $('#example-stop-results').innerHTML=exampleAdded?`<div class="panel"><h2>どの停留所で、何本増えた？</h2>${table(['停留所・乗り場','変更前の本数','1便追加した後'],result.rows.map(r=>[esc(r.name),fmt(r.before)+'便',`<b class="gain">${fmt(r.after)}便（+${fmt(r.after-r.before)}）</b>`]))}</div>`:'';
  if(document.body.dataset.page!=='example')return;
  if(!exampleMap){exampleMap=L.map('example-map',{scrollWheelZoom:false}).setView([33.28,131.15],11);L.tileLayer('https://cyberjapandata.gsi.go.jp/xyz/pale/{z}/{x}/{y}.png',{maxZoom:18,attribution:'背景：<a href="https://maps.gsi.go.jp/development/ichiran.html" target="_blank" rel="noopener">地理院タイル</a>｜交通：大分県・CC BY 4.0'}).addTo(exampleMap);exampleMarkers=L.layerGroup().addTo(exampleMap)}
  exampleMarkers.clearLayers();for(const r of result.rows)L.circleMarker([r.lat,r.lon],{radius:exampleAdded?8:6,color:'white',weight:1.5,fillColor:exampleAdded?'#087e80':'#215ec7',fillOpacity:.95}).addTo(exampleMarkers).bindPopup(`<b>${esc(r.name)}</b><br>変更前 ${r.before}便 → ${exampleAdded?'追加後':'現在'} ${r.after}便`);
  setTimeout(()=>{exampleMap.invalidateSize();if(result.rows.length)exampleMap.fitBounds(L.latLngBounds(result.rows.map(r=>[r.lat,r.lon])),{padding:[24,24],maxZoom:14})},20);
}

function setupMap(){if(!window.L)throw Error('地図ライブラリを読み込めません');map=L.map('lab-map',{preferCanvas:true,scrollWheelZoom:false}).setView([33.3,131.25],10);L.tileLayer('https://cyberjapandata.gsi.go.jp/xyz/pale/{z}/{x}/{y}.png',{maxZoom:18,attribution:'背景：<a href="https://maps.gsi.go.jp/development/ichiran.html" target="_blank" rel="noopener">地理院タイル</a>｜交通：大分県・CC BY 4.0'}).addTo(map);shapeLayer=L.layerGroup().addTo(map);markers=L.layerGroup().addTo(map);odLayer=L.layerGroup().addTo(map)}
function setOptions(id,options){const el=$(id),old=el.value;el.innerHTML=options;if([...el.options].some(x=>x.value===old))el.value=old}
function renderScenarioSelect(){setOptions('#scenario-select',state.scenarios.map(s=>opt(s.id,s.name)).join(''));$('#scenario-select').value=state.selected}
function filter(){const [start,end]=$('#time-window').value.split(',').map(Number);return {route:$('#route-select').value,direction:$('#direction-select').value,start,end}}
async function refresh({fit=false}={}){
  if(!state.feeds.length)throw Error('GTFSを読み込んでください');const revision=++latestRevision;analysis=null;message('基準ダイヤと変更案を再計算しています…',true);changed=scenarioFeeds(state.feeds,scenario().edits);reach=null;$('#reach-results').innerHTML=empty('出発地と時刻を選び「行ける停留所を比較」を押すと、地図と一覧に結果が出ます。');
  const routeOptions='<option value="all">すべての路線</option>'+changed.flatMap(f=>f.tables.routes.map(r=>opt(key(f.id,r.route_id),(r.route_long_name||r.route_short_name||r.route_id)+' · '+f.name))).join('');setOptions('#route-select',routeOptions);
  const result=await request('prepare',{feeds:state.feeds,edits:scenario().edits,date:$('#analysis-date').value,filter:filter()});if(revision!==latestRevision)return;
  analysis=result;scenario().supply={date:$('#analysis-date').value,filter:filter(),before:result.before,after:result.after};
  renderEditor();renderSupply();$('#working-context').textContent=state.feeds.map(f=>f.name).join('・')+' ／ '+$('#analysis-date').value+' ／ '+scenario().name+' ／ 変更 '+scenario().edits.length+'件';renderFeeds();renderQuality();renderChanges();renderComparison();drawMap();
  const options=Object.values(analysis.stops).sort((a,b)=>a.name.localeCompare(b.name,'ja')).map(s=>opt(s.key,s.name+' · '+s.feed)).join('');setOptions('#reach-origin',options);
  if(fit)fitMap();message(`${state.feeds.length}データ · ${Object.keys(result.stops).length.toLocaleString()}乗り場 · 基準 ${result.before.trips}便 → 変更案 ${result.after.trips}便${result.excluded?' · 除外便あり':''}`);
}
function renderSupply(){
  const {before:a,after:b}=analysis;$('#supply-metrics').innerHTML=metric('選んだ条件の便数',`${fmt(a.trips)} → ${fmt(b.trips)}`,`変更案 ${signed(b.trips-a.trips)}便`)+metric('バスに乗れる乗り場',`${fmt(a.stops)} → ${fmt(b.stops)}`,'選んだ路線・時間帯で比較')+metric('バスが走る時間',`${fmt(b.vehicleHours,1)}時間`,`基準比 ${signed(b.vehicleHours-a.vehicleHours,1)}時間 · 回送・休憩を除く`)+metric('変更操作',`${scenario().edits.length}件`,'元の時刻表から変えた操作の数');
  const max=Math.max(1,...a.hours,...b.hours),hours=Array.from({length:24},(_,i)=>i);$('#hourly-chart').innerHTML='<p class="meta">始発時刻別：灰＝基準、青＝変更案。24時以降の便は下の算定表に含みます。</p><div class="bar-chart">'+hours.map(h=>`<div class="bar-group" title="${h}時：基準${a.hours[h]}便、変更${b.hours[h]}便"><i style="height:${a.hours[h]/max*100}%"></i><i class="after" style="height:${b.hours[h]/max*100}%"></i><span>${h}</span></div>`).join('')+'</div>';
  const rows=stopDiff();$('#stop-differences').innerHTML=table(['停留所・乗り場','出発数 基準→案','増減','始発 基準→案','最終 基準→案'],rows.slice(0,100).map(r=>[`<button class="action-link" data-focus-stop="${esc(r.key)}">${esc(r.name)}</button><small>${esc(r.key)}</small>`,`${r.before} → ${r.after}`,`<span class="${r.delta<0?'loss':r.delta>0?'gain':''}">${signed(r.delta)}</span>`,`${r.first0??'—'} → ${r.first1??'—'}`,`${r.last0??'—'} → ${r.last1??'—'}`]))+`<p class="meta">${fmt(rows.length)}乗り場中、差の大きい順に最大100件。全件をCSV出力できます。同じ停留所名も事業者別IDを保持します。</p>`;
}
function stopDiff(){if(!analysis)return [];const {before:a,after:b,stops}=analysis;return [...new Set([...Object.keys(a.byStop),...Object.keys(b.byStop)])].map(k=>({key:k,name:stops[k]?.name??k,before:a.byStop[k]?.departures??0,after:b.byStop[k]?.departures??0,delta:(b.byStop[k]?.departures??0)-(a.byStop[k]?.departures??0),first0:a.byStop[k]?clock(a.byStop[k].first):null,first1:b.byStop[k]?clock(b.byStop[k].first):null,last0:a.byStop[k]?clock(a.byStop[k].last):null,last1:b.byStop[k]?clock(b.byStop[k].last):null})).sort((x,y)=>Math.abs(y.delta)-Math.abs(x.delta)||y.after-x.after)}
function fitMap(){const stops=Object.values(analysis?.stops??{});if(stops.length)map.fitBounds(L.latLngBounds(stops.map(s=>[s.lat,s.lon])),{padding:[20,20],maxZoom:13})}
function drawMap(){
  if(!analysis||!map)return;$('#map-riders').disabled=!rideResult;$('#map-od').disabled=!odResult;$('#map-riders').title=rideResult?'乗り降りした人数を表示':'乗客の実績画面から集計CSVを取り込むと使えます';$('#map-od').title=odResult?'移動先を表示':'乗客の実績画面から移動集計CSVを取り込むと使えます';markers.clearLayers();shapeLayer.clearLayers();odLayer.clearLayers();
  for(const f of changed){const selectedRoutes=new Set(f.tables.trips.filter(t=>filter().route==='all'||key(f.id,t.route_id)===filter().route).map(t=>t.shape_id).filter(Boolean)),shapes=new Map();for(const r of f.tables.shapes??[])if(selectedRoutes.has(r.shape_id)){if(!shapes.has(r.shape_id))shapes.set(r.shape_id,[]);shapes.get(r.shape_id).push(r)}for(const rows of shapes.values()){rows.sort((a,b)=>Number(a.shape_pt_sequence)-Number(b.shape_pt_sequence));L.polyline(rows.map(r=>[Number(r.shape_pt_lat),Number(r.shape_pt_lon)]),{weight:1.4,color:'#659ca9',opacity:.28,interactive:false,smoothFactor:1.4}).addTo(shapeLayer)}}
  const diffs=new Map(stopDiff().map(r=>[r.key,r])),reachRows=new Map((reach?.comparison??[]).map(r=>[r.stop,r])),riders=new Map((rideResult?.byStop??[]).map(r=>[r.stop,r]));
  for(const s of Object.values(analysis.stops)){
    let color='#a5b4bf',radius=3,note='';const d=diffs.get(s.key),r=reachRows.get(s.key),observed=riders.get(s.key);
    if(mapMode==='supply'){if(!d)continue;color=d.delta>0?'#087e80':d.delta<0?'#ba543c':'#6689ad';radius=d.delta?6:3;note=`出発数：${d.before} → ${d.after}（${signed(d.delta)}）`}
    if(mapMode==='access'){if(!r)continue;color=({'新たに到達':'#087e80','到達不可':'#ba543c','短縮':'#215ec7','延長':'#bc8332','変化なし':'#a5b4bf'})[r.change];radius=r.change==='変化なし'?3:6;note=`${r.change}：${fmt(r.before,1)} → ${fmt(r.after,1)}分`}
    if(mapMode==='riders'){if(!observed)continue;color='#725fa4';radius=Math.min(14,4+Math.sqrt(observed.boardings+observed.alightings)/2);note=`取込実績 乗車${fmt(observed.boardings)}・降車${fmt(observed.alightings)}回`}
    L.circleMarker([s.lat,s.lon],{radius,color:'white',weight:.7,fillColor:color,fillOpacity:.9}).addTo(markers).bindPopup(`<b>${esc(s.name)}</b><br>${esc(s.key)}<br>${note}<br><button class="button" data-origin="${esc(s.key)}">到達比較の起点にする</button>`);
  }
  if(mapMode==='od'&&odResult){for(const r of [...odResult.cells].filter(r=>r.status==='observed'&&r.count>0).sort((a,b)=>b.count-a.count).slice(0,100)){const a=analysis.stops[r.origin],b=analysis.stops[r.destination];if(a&&b)L.polyline([[a.lat,a.lon],[b.lat,b.lon]],{color:'#75579d',weight:Math.min(9,1+Math.log1p(r.count)),opacity:.65}).addTo(odLayer).bindPopup(`${esc(a.name)} → ${esc(b.name)}<br>${fmt(r.count)}回（提供されたOD集計）`)}}
  const legends={supply:[['#087e80','増便'],['#ba543c','減便'],['#6689ad','変更なし']],access:[['#087e80','新たに到達'],['#ba543c','到達不可'],['#215ec7','短縮'],['#bc8332','延長']],riders:[['#725fa4','取込済みの公表・事業者集計']],od:[['#75579d','提供OD（線を押すと方向・人数）']]};$('#map-legend').innerHTML=legends[mapMode].map(([c,t])=>`<span><i style="--dot:${c}"></i>${t}</span>`).join('');
  $('#map-caption').textContent=mapMode==='od'?'ODは上位100組。直線は起終点の関係であり、実際の移動経路ではありません。':mapMode==='access'?'到達する乗り場の比較。歩行道路・面積・人口カバー率・帰宅条件は未評価です。':mapMode==='riders'?'乗降の観測期間は実績画面で確認。地図の運行予定日と自動合算しません。':'丸は事業者別の乗り場。線は原GTFSの形状で、停車列変更便の形状は除外しています。';
  $$('.map-panel .segmented button').forEach(b=>b.classList.toggle('selected',b.id==='map-'+({access:'access',riders:'riders',od:'od',supply:'supply'})[mapMode]));
}
function renderEditor(){setOptions('#edit-feed',changed.map(f=>opt(f.id,f.name)).join(''));renderRoutes()}
function renderRoutes(){const f=currentFeed();if(!f)return;setOptions('#edit-route',f.tables.routes.map(r=>opt(r.route_id,r.route_long_name||r.route_short_name||r.route_id)).join(''));renderTrips();const stops=f.tables.stops.map(s=>opt(s.stop_id,s.stop_name+' · '+s.stop_id)).join('');setOptions('#insert-stop',stops);setOptions('#edit-stop',stops);renderStopEditor()}
function renderTrips(){const f=currentFeed();if(!f)return;const route=f.tables.routes.find(r=>r.route_id===$('#edit-route').value);$('#edit-route-name').value=route?.route_long_name||route?.route_short_name||'';const trips=f.tables.trips.filter(r=>r.route_id===$('#edit-route').value);setOptions('#edit-trip',trips.map(t=>{const first=f.tables.stop_times.filter(r=>r.trip_id===t.trip_id).sort((a,b)=>Number(a.stop_sequence)-Number(b.stop_sequence))[0];return opt(t.trip_id,(first?.departure_time??'')+' '+(t.trip_headsign??'')+' · '+t.trip_id)}).join(''));renderTripEditor()}
function renderTripEditor(){const f=currentFeed(),trip=$('#edit-trip').value;if(!f)return;const rows=f.tables.stop_times.filter(r=>r.trip_id===trip).sort((a,b)=>Number(a.stop_sequence)-Number(b.stop_sequence));renderCalls(rows)}
function renderCalls(rows){callDraft=structuredClone(rows);const f=currentFeed();$('#trip-editor').innerHTML=table(['停留所','到着','出発','操作'],rows.map((r,i)=>[`${esc(f.tables.stops.find(s=>s.stop_id===r.stop_id)?.stop_name??r.stop_id)}<input type="hidden" data-call="${i}" data-field="stop_id" value="${esc(r.stop_id)}"><input type="hidden" data-call="${i}" data-field="pickup_type" value="${esc(r.pickup_type??'0')}"><input type="hidden" data-call="${i}" data-field="drop_off_type" value="${esc(r.drop_off_type??'0')}">`,`<input data-call="${i}" data-field="arrival_time" value="${esc(r.arrival_time)}" aria-label="${i+1}番目の到着時刻">`,`<input data-call="${i}" data-field="departure_time" value="${esc(r.departure_time)}" aria-label="${i+1}番目の出発時刻">`,`<button class="button" data-delete-call="${i}">除く</button>`]));}
function editedCalls(){const rows=structuredClone(callDraft);$$('#trip-editor [data-call]').forEach(input=>{const i=Number(input.dataset.call);rows[i]??={};rows[i][input.dataset.field]=input.value});return rows}
function renderStopEditor(){const f=currentFeed(),s=f?.tables.stops.find(r=>r.stop_id===$('#edit-stop').value);if(!s)return;$('#edit-stop-name').value=s.stop_name;$('#edit-lat').value=s.stop_lat;$('#edit-lon').value=s.stop_lon}
async function addEdit(edit){const next=scenarioFeeds(state.feeds,[...scenario().edits,edit]),q=validateFeeds(next);if(q.errors)throw Error(q.issues.find(r=>r.level==='error').message);scenario().edits.push({...edit,at:new Date().toISOString()});invalidateScenario();scenario().reach=null;await refresh();}
function renderChanges(){const names={shift:'時刻変更',duplicate:'便を追加',cancel:'便を削除',stop_time:'時刻を直接編集',calls:'停車列を変更',stop:'停留所を編集',new_stop:'停留所を追加',route:'路線名を編集'};$('#change-log').innerHTML=table(['順番','変更','対象','内容'],scenario().edits.map((e,i)=>[i+1,names[e.type]??esc(e.type),esc(e.feed+' / '+(e.trip??e.id??e.values?.stop_id??'')),esc(e.minutes!==undefined?signed(Number(e.minutes))+'分':JSON.stringify(e.values??e.rows??{}).slice(0,300))]));$('#undo-edit').disabled=!scenario().edits.length}
async function calculateReach(){if(!analysis)throw Error('運行データを先に読み込んでください');message('乗換・待ち時間を含めて到達先を比較しています…',true);const options={origin:$('#reach-origin').value,departure:seconds($('#reach-time').value+':00'),budget:Number($('#reach-budget').value)*60,maxTransfers:Number($('#reach-transfers').value),maxWalk:Number($('#walk-distance').value),walkSpeed:Number($('#walk-speed').value),transferMinutes:Number($('#transfer-buffer').value)};const revision=latestRevision;const result=await request('reach',options);if(revision!==latestRevision)return;reach=result;scenario().reach={date:$('#analysis-date').value,options,result};const rows=result.comparison.sort((a,b)=>['到達不可','新たに到達','延長','短縮','変化なし'].indexOf(a.change)-['到達不可','新たに到達','延長','短縮','変化なし'].indexOf(b.change));
  $('#reach-results').className='';$('#reach-results').innerHTML=`<div class="metrics">${metric('基準の到達乗り場',fmt(Object.keys(result.before.best).length))}${metric('変更案の到達乗り場',fmt(Object.keys(result.after.best).length))}${metric('新たに到達',fmt(rows.filter(r=>r.change==='新たに到達').length),'乗り場数・同名重複を含む')}${metric('到達できなくなる',fmt(rows.filter(r=>r.change==='到達不可').length),'個別の移動への影響を要確認')}</div>${table(['乗り場','基準 分','変更案 分','変化'],rows.slice(0,100).map(r=>[`<button class="action-link" data-focus-stop="${esc(r.stop)}">${esc(r.name)}</button>`,fmt(r.before,1),fmt(r.after,1),esc(r.change)]))}<p class="meta">徒歩だけで到達する乗り場も含みます。最大100件を表示、全件をCSV出力。</p>`;mapMode='access';drawMap();renderComparison();message('到達比較が完了しました。失われる到達先も表に表示しています。');}

