async function loadSeed(replace=false){const item=catalog.find(c=>c.file===$('#seed-select').value);if(!item)throw Error('公開データを選んでください');message(item.name+'を読み込んでいます…',true);const response=await fetch('data/gtfs/'+encodeURIComponent(item.file));if(!response.ok)throw Error('公開GTFSを読み込めませんでした');await acceptFeed(await response.arrayBuffer(),item.name,replace,item)}
async function acceptFeed(buffer,name,replace=false,source=null){
  if(buffer.byteLength>35*1024*1024)throw Error('圧縮前ファイルが大きすぎます。35MB以内に分けてください');const id=replace?'f1':'f'+(Math.max(0,...state.feeds.map(f=>Number(f.id.slice(1))||0))+1),f=await importGTFS(buffer,name,id);
  if(!replace&&state.feeds.some(x=>x.hash===f.hash))throw Error('同じGTFSはすでに読み込まれています');const q=validateFeeds([f]);if(q.errors)throw Error(`GTFSに${q.errors}件のエラー：${q.issues.filter(r=>r.level==='error').slice(0,3).map(r=>r.message).join('／')}`);
  Object.assign(f,{source:source?.source??'',catalog:source?.catalog??'',retrieved:source?.retrieved??'',license:source?.license??'提供者の条件を確認',licenseUrl:source?.licenseUrl??'',attribution:source?.attribution??''});
  if(replace){state.feeds=[f];state.scenarios.forEach(s=>{s.edits=[];delete s.supply;delete s.reach;delete s.demand;if(s.economic)s.economic.stale=true});state.observations=null;state.od=null;rideResult=null;odResult=null;$('#observed-results').innerHTML=empty('乗降データは未取込です。');$('#od-results').innerHTML=empty('ODデータは未取込です。')}else{state.feeds.push(f);state.scenarios.forEach(s=>{delete s.supply;delete s.reach;delete s.demand;if(s.economic)s.economic.stale=true})}await refresh({fit:true});renderEconomics();
}
const rideColumns=['service_date','feed_id','trip_id','stop_sequence','stop_id','boardings','alightings'],odColumns=['origin_feed_id','origin_stop_id','destination_feed_id','destination_stop_id','count','status'];
function observationMeta(){return {source:$('#obs-source').value.trim(),from:$('#obs-from').value,to:$('#obs-to').value,scope:$('#obs-scope').value.trim(),basis:$('#obs-basis').value,complete:$('#obs-complete').value,initialEmpty:$('#obs-initial').value,finalEmpty:$('#obs-final').value,unit:$('#od-unit').value,timezone:'Asia/Tokyo',hash:loadedCSV?.hash??null,feedHashes:state.feeds.map(f=>({id:f.id,hash:f.hash}))}}
async function loadObservedFile(){const file=$('#observed-file').files[0];if(!file)return;if(file.size>20*1024*1024)throw Error('集計CSVは20MB以内に分けてください');const buffer=await file.arrayBuffer(),rows=parseCSV(new TextDecoder($('#csv-encoding').value,{fatal:true}).decode(buffer));if(!rows.length)throw Error('CSVが空です');if(Object.keys(rows[0]).some(k=>/card.?id|person.?id|user.?id|device.?id|email|氏名|電話番号|カード.?番号|カード.?id|会員番号|個人id/i.test(k)))throw Error('個人・カード等を識別する列が含まれています。事業者側で集計したCSVを用意してください');loadedCSV={rows,name:file.name,hash:await sha256(buffer)};renderMapping();}
function renderMapping(){if(!loadedCSV)return;const kind=$('#import-kind').value,columns=kind==='od'?[...odColumns]:[...rideColumns],headers=Object.keys(loadedCSV.rows[0]);if(kind==='ridership'&&headers.includes('trip_start_time'))columns.push('trip_start_time');const aliases={service_date:['日付','運行日'],trip_id:['便ID'],stop_id:['停留所ID'],stop_sequence:['停車順'],boardings:['乗車','乗車人数','乗車人員'],alightings:['降車','降車人数','降車人員'],count:['人数','件数']};
  $('#column-mapping').className='';$('#column-mapping').innerHTML=`<p class="meta">${esc(loadedCSV.name)} · ${fmt(loadedCSV.rows.length)}行。左の標準項目に元CSVの列を指定します。</p>`+columns.map(c=>`<div class="mapping-row"><label for="mapping-${c}">${esc(c)}</label><select id="mapping-${c}" data-mapping="${c}">${opt('','選んでください')}${headers.map(h=>opt('column:'+h,h)).join('')}${c.includes('feed_id')?state.feeds.map(f=>opt('fixed:'+f.id,'固定値 '+f.id+' '+f.name)).join(''):''}${c==='service_date'?opt('date:','固定値 観測開始日'):''}${c==='status'?opt('fixed:observed','固定値 observed（観測値）'):''}</select></div>`).join('');
  columns.forEach(c=>{const match=headers.includes(c)?c:(aliases[c]??[]).find(a=>headers.includes(a));$('#mapping-'+c).value=match?'column:'+match:c.includes('feed_id')&&state.feeds.length===1?'fixed:'+state.feeds[0].id:c==='status'?'fixed:observed':''});$('#apply-observed').disabled=false;
}
function mappedRows(){return loadedCSV.rows.map(row=>Object.fromEntries($$('[data-mapping]').map(select=>{const value=select.value;if(!value)throw Error(select.dataset.mapping+' の対応列を選んでください');return [select.dataset.mapping,value.startsWith('column:')?row[value.slice(7)]:value.startsWith('fixed:')?value.slice(6):$('#obs-from').value]})))}
function runObserved(){if(!loadedCSV)throw Error('CSVを選んでください');const rows=mappedRows(),meta=observationMeta();if($('#import-kind').value==='od'){state.od={rows,meta};odResult=analyzeOD(rows,state.feeds,meta);renderODResult()}else{state.observations={rows,meta};rideResult=analyzeRidership(rows,state.feeds,meta);renderRideResult()}drawMap();message('集計と照合が完了しました。不一致の行・欠測は別に表示しています。')}
function renderRideResult(){if(!rideResult)return;const r=rideResult;$('#observed-results').className='';$('#observed-results').innerHTML=`<div class="panel"><h2>便・停留所別の乗降実績</h2><p>${esc(r.meta.source)} · ${esc(r.meta.from)}〜${esc(r.meta.to)} · ${esc(r.meta.scope)}</p>${r.errors.length?`<div class="error">${r.errors.map(esc).join('<br>')}</div>`:''}<div class="metrics">${metric('照合できた乗車回数',fmt(r.boardings),'取込済みの対象内合計・実人数ではない')}${metric('照合できた降車回数',fmt(r.alightings))}${metric('観測された便',fmt(r.observedTrips),'GTFS予定便を観測便数に代用しない')}${metric('不一致・不正な行',fmt(r.unmatched.length),r.unmatched.length?'全件CSVを出力して修正してください':'全行のID・日付照合完了')}</div><button class="button" id="riders-on-map">乗降実績を地図で見る</button>${table(['乗り場','乗車回数','降車回数'],r.byStop.sort((a,b)=>b.boardings-a.boardings).slice(0,60).map(s=>[esc(analysis?.stops[s.stop]?.name??s.stop),fmt(s.boardings),fmt(s.alightings)]))}<h3>区間別の車内人数</h3><p class="meta">各停留所を出た後の人数。全停車箇所の観測と起点0人の確認が必要です。不整合がある便では車内人数を算定しません。</p>${table(['観測日・便','状態','最大車内人数','観測行 / 必要行'],r.loads.map(g=>[esc(g.key),g.state==='valid'?'算定可能':g.state==='invalid'?'乗降差が不整合':'全停車観測・初期人数等が未確認',g.peak===null?'算定不可':fmt(g.peak)+'人',`${g.rows.length} / ${g.expected}`]))}<details><summary>各停車箇所の車内人数を確認</summary>${table(['便','停車順','停留所','乗車','降車','出発後の車内人数'],r.loads.flatMap(g=>g.series.map(s=>[esc(g.trip),esc(s.stop_sequence),esc(analysis?.stops[s.stopKey]?.name??s.stop_id),fmt(s.boardings),fmt(s.alightings),fmt(s.load)])).slice(0,200))}</details>${r.unmatched.length?`<h3>照合できなかった行</h3>${table(['元CSV行','理由'],r.unmatched.slice(0,50).map(x=>[x.row,esc(x.error)]))}`:''}</div>`;on('#riders-on-map','click',()=>{mapMode='riders';location.hash='design';drawMap()})}
function renderODResult(){if(!odResult)return;const r=odResult,zones=[...new Set(r.cells.flatMap(c=>[c.origin,c.destination]))].slice(0,14),cellMap=new Map(r.cells.map(c=>[c.origin+'|'+c.destination,c]));const cell=(o,d)=>{const c=cellMap.get(o+'|'+d);if(!c||c.status!=='observed')return `<td class="unknown">${c?.status==='suppressed'?'非表示':'未収録'}</td>`;return `<td style="background:rgba(117,87,157,${.05+Math.min(.5,Math.log1p(c.count)/20)})">${fmt(c.count)}</td>`};$('#od-results').className='';$('#od-results').innerHTML=`<div class="panel"><h2>起点・終点の提供OD</h2><p>${esc(r.meta.source)} · ${esc(r.meta.from)}〜${esc(r.meta.to)} · ${esc(r.meta.scope)}</p><p class="meta">${r.meta.unit==='journeys'?'乗換を含む一連の移動':'車両ごとの乗車'}。提供された観測セル合計 ${fmt(r.total)}回、${r.observed}セル。非表示 ${r.suppressed}セル。全県総量・実人数ではありません。</p><button class="button" id="od-on-map">ODを地図で見る</button><div class="table-wrap"><table class="data-table heatmap"><thead><tr><th>起点 ↓ / 終点 →</th>${zones.map(k=>`<th>${esc(analysis?.stops[k]?.name??k)}</th>`).join('')}</tr></thead><tbody>${zones.map(o=>`<tr><th scope="row">${esc(analysis?.stops[o]?.name??o)}</th>${zones.map(d=>cell(o,d)).join('')}</tr>`).join('')}</tbody></table></div><p class="meta">行列は最大14乗り場。全ペアはCSV出力に収録。未収録・非表示と、明示された0を区別します。乗降の合計からODを推測して埋めません。</p>${r.errors.length?`<h3>取込エラー ${r.errors.length}件</h3>${table(['行','内容'],r.errors.slice(0,50).map(e=>[e.row??'条件',esc(e.error)]))}`:''}</div>`;on('#od-on-map','click',()=>{mapMode='od';location.hash='design';drawMap()})}
function observedTemplate(){const f=state.feeds[0];if(!f)throw Error('GTFSを先に読み込んでください');if($('#import-kind').value==='od'){const stops=f.tables.stops.slice(0,3),rows=stops.slice(1).map(s=>({origin_feed_id:f.id,origin_stop_id:stops[0].stop_id,destination_feed_id:f.id,destination_stop_id:s.stop_id,count:'',status:'observed'}));download('od-template.csv','\uFEFF'+csvText(rows,{safe:true}),'text/csv;charset=utf-8')}else{const selected=currentFeed()??f,trip=selected.tables.trips.find(t=>t.trip_id===$('#edit-trip').value)??selected.tables.trips[0],rows=selected.tables.stop_times.filter(r=>r.trip_id===trip.trip_id).sort((a,b)=>Number(a.stop_sequence)-Number(b.stop_sequence)).map(r=>({service_date:$('#analysis-date').value,feed_id:selected.id,trip_id:r.trip_id,stop_sequence:r.stop_sequence,stop_id:r.stop_id,boardings:'',alightings:''}));download('ridership-template.csv','\uFEFF'+csvText(rows,{safe:true}),'text/csv;charset=utf-8')}message('テンプレートの人数は空欄です。実績値を入力して取り込んでください。')}
function calculateForecast(){const rows=parseCSV($('#forecast-input').value),frequency=$('#forecast-frequency').value,horizon=Number($('#forecast-horizon').value),source=$('#forecast-source').value.trim();if(!source)throw Error('予測する実績の出典・対象範囲を入力してください');forecastResult=forecast(rows,frequency,horizon);state.forecast={rows,frequency,horizon,source,result:forecastResult};const r=forecastResult;$('#forecast-results').innerHTML=`<div class="panel"><h2>予測と過去検証の結果</h2><p>${esc(source)}</p><div class="notice ${r.sufficient?'':'amber'}">${r.sufficient?'同じ検証時点でのMAEを比較しました。':'過去検証が3件未満のため、方式の優劣は未確定です。'} 延長値は${r.chosen==='trend'?'傾向モデル':'基準モデル'}を選択。施策効果・潜在需要の推定ではありません。</div><div class="metrics">${metric('同じ条件での過去検証',r.folds.length+'回','1期間先。将来の全年数の精度保証ではない')}${metric('基準モデルのMAE',fmt(r.scores.baseline,1),'人数の絶対誤差の平均')}${metric('傾向モデルのMAE',fmt(r.scores.trend,1),'直近最大5点／月次季節差分')}${metric('選択した方法',r.chosen==='trend'?'傾向':'基準','同点・検証不足では基準モデル')}</div>${table(['将来期間','基準の延長','傾向の延長','選択した延長値'],r.future.map(f=>[esc(f.period),fmt(f.baseline,1),fmt(f.trend,1),fmt(f[r.chosen],1)]))}<details><summary>検証期間ごとの実績と誤差</summary>${table(['検証対象','実績','基準予測','傾向予測','基準の絶対誤差','傾向の絶対誤差'],r.folds.map(f=>[f.period,fmt(f.actual),fmt(f.baseline,1),fmt(f.trend,1),fmt(Math.abs(f.actual-f.baseline),1),fmt(Math.abs(f.actual-f.trend),1)]))}</details></div>`;message('時系列の延長値と、過去時点だけを使った検証結果を更新しました。')}
function calculateDemand(){if(!$('#demand-comparable').checked)throw Error('路線長・時間帯・曜日構成の比較条件を確認してください');if(scenario().edits.some(e=>e.type==='calls'||e.type==='new_stop'))throw Error('停車列・経路を変更した案には供給量だけの感度式を適用できません');const options={baseline:$('#demand-baseline').value,f0:$('#demand-f0').value,f1:$('#demand-f1').value,elasticities:$('#elasticities').value.split(',').map(x=>num(x)),method:$('#elasticity-method').value};if(options.elasticities.length<1||options.elasticities.length>10)throw Error('係数は1〜10個で指定してください');const r=demandSensitivity(options);state.demand={options,result:r,scenario:state.selected,date:$('#analysis-date').value,scope:filter()};scenario().demand=state.demand;$('#demand-results').innerHTML=r.available?`<div class="result-hero"><span>仮定による年間乗車回数の範囲</span><strong>${fmt(r.low)}〜${fmt(r.high)}</strong><p>信頼区間ではありません。${esc(r.reason??'係数の仮定を変えた感度範囲です。')}</p></div>${table(['係数の仮定','年間乗車回数'],r.values.map(v=>[fmt(v.elasticity,2),fmt(v.demand)]))}`:empty(esc(r.reason));renderComparison();message('供給変更に対する感度試算を更新しました。')}

function econParameters(){const p=Object.fromEntries(new FormData($('#econ-form')));if(!p.without.trim()||!p.source.trim())throw Error('現状維持案と出典・対象範囲を入力してください');if(!$('#econ-scope').checked)throw Error('比較の対象・期間・価格基準を確認してください');num(p.priceYear,{integer:true});if(!['journeys','legs'].includes(p.unit))throw Error('便益を計算する人数・時間の単位を選んでください');return p}
function calculateEconomics(custom=null){const p=econParameters(),rows=custom??generatedCashflow(p),options={rate:num(p.rate)/100,baseYear:num(p.baseYear,{integer:true}),vot:num(p.vot)},result=economics(rows,options),sensitivities=economicSensitivity(rows,options),switchPoint=switchingDemand(rows,options);scenario().economicDraft={...p};scenario().economic={unit:p.unit,welfareIncomplete:!p.lossMethod?.trim(),parameters:p,rows,options,result,sensitivities,switchPoint,confirmedScope:true,custom:!!custom,stale:false};econResult=result;renderEconomics();renderComparison();message('年別の費用便益・収支・感度・損益分岐を再計算しました。')}
function renderEconomics(){const e=scenario().economic;if(!e){$('#econ-results').className='empty';$('#econ-results').textContent='この案の費用便益は未算定です。評価条件を入力してください。';$('#econ-tables').innerHTML='';return}const r=e.result;$('#econ-results').className='';$('#econ-results').innerHTML=`<div class="result-hero"><span>算定範囲内のB/C（利用者・運営者便益／投資費）</span><strong>${r.bc===null?'算定対象外':fmt(r.bc,2)}</strong><p>${r.bc===null?'増分の投資費が0のため、この計上方式の比率は出せません。':'台形近似による利用者便益＋事業者の増分利益を含む部分評価。'}${e.stale?'条件が変わっています。再計算が必要です。':''}${e.welfareIncomplete?' 到達できなくなる移動等の評価方法が未入力です。便益評価は未完了です。':''}</p><div class="metrics">${metric('純便益の現在価値 NPV',money(r.npv))}${metric('費用現在価値',money(r.pvCost),'投資・更新・撤去費')}</div></div><div class="panel"><h2>計上方法を確認</h2>${table(['項目','現在価値'],[['利用者便益',money(r.pvUser)],['運営者便益（増分収入−増分運行費）',money(r.pvProvider)],['外部便益',r.externalUnassessed?'一部または全期間が未評価':money(r.pvExternal)],['最終年の残存価値',money(r.pvResidual)],['資源費用方式の部分B/C',r.resourceBC===null?'増分費用が0以下のため算定対象外':fmt(r.resourceBC,2)]])}<p class="meta">資源費用方式では運行費の増分を分母へ移します。NPVは同じですがB/Cの数値は異なります。未評価の外部影響をゼロと確認したものではありません。</p><p class="meta">${esc(e.parameters.source)} · ${esc(e.parameters.priceYear)}年価格 · 割引率${fmt(e.options.rate*100,1)}%。${e.custom?'年別CSV入力。':'初期投資は基準年、供用開始年以降は年末発生。'}</p></div>`;
  $('#econ-tables').innerHTML=`<div class="panel"><h2>下振れ・損益分岐</h2>${table(['条件','部分B/C','純便益 NPV'],e.sensitivities.map(s=>[esc(s.name),fmt(s.bc,2),money(s.npv)]))}<p>NPVが0になる需要倍率：<strong>${e.switchPoint?fmt(e.switchPoint.multiplier,3)+'倍':'非負の倍率では求まりません'}</strong></p><p class="meta">同じ市場の両案需要を同時に変え、対応する利用者便益と運賃収入を再計算。費用・係数・交通条件の独立性も仮定です。</p></div><div class="panel"><h2>年別の費用・便益と運営収支</h2>${table(['年','利用者便益','運営者便益','投資等費用','割引後の純便益','運営収支 基準','運営収支 変更'],r.cashflows.map(c=>[c.year,money(c.userBenefit),money(c.providerBenefit),money(c.cost),money(c.npv),money(c.operatorBalance0),money(c.operatorBalance1)]))}<p class="meta">運営収支は運賃収入−運行費。資本調達、借入返済、補助金は別途の資金計画が必要です。運行費用から補助金を差し引いて社会的費用を小さくしていません。</p></div><details><summary>計算式・数値の範囲</summary><p>年間利用者便益＝0.5×（変更しない乗車回数＋変更する乗車回数）×｛（基準時間−変更時間）×時間価値＋（基準運賃−変更運賃）｝。</p><p>運営者便益＝変更案の運賃収入−基準の運賃収入−（変更案の運行資源費−基準の運行資源費）。便益＝利用者便益＋運営者便益＋評価した外部便益＋最終年残存価値。費用＝追加投資＋更新＋撤去。</p><p>年yの割引係数＝(1＋割引率)^−(y−基準年)。NPV＝便益現在価値−費用現在価値。人数は同じ市場・年間の移動回数で、増加分すべてに既存利用者と同じ便益を配賦しません。</p><p>道路交通量・速度・事故・CO2・人口カバー率の自動推計は含みません。外部便益の入力には、追加バスの排出と自動車からの転換を区別した別途の根拠が必要です。これは正式評価の完了を意味しません。</p></details>`;
}
function restoreEconomicForm(){const form=$('#econ-form');form.reset();const e=scenario().economic,draft=scenario().economicDraft??e?.parameters;if(draft){for(const [name,value]of Object.entries(draft))if(form.elements.namedItem(name))form.elements.namedItem(name).value=value;$('#econ-scope').checked=e?.confirmedScope??false}econResult=e?.result??null;renderEconomics()}
function exampleEconomics(){const p={unit:'journeys',lossMethod:'',without:'既存バスを維持する将来（操作例）',source:'操作確認用の仮定。実在事業の評価・費用見積りではない。',baseYear:2026,opening:2027,years:10,priceYear:2026,rate:4,vot:35,q0:30000,q1:33000,time0:45,time1:40,fare0:300,fare1:300,opex0:2000,opex1:2150,capital:1000,growth:0,replaceEvery:6,replacement:500,residual:200,external:''};for(const [name,value]of Object.entries(p))$('#econ-form').elements.namedItem(name).value=value;$('#econ-scope').checked=false;message('操作例を入力しました。仮定を確認し、計算ボタンを押してください。')}
function invalidateScenario(){const s=scenario();delete s.reach;delete s.demand;if(s.economic)s.economic.stale=true;state.demand=null;$('#demand-results').innerHTML=empty('変更案が更新されました。条件を確認して再計算してください。');renderEconomics()}
function economicSignature(e){return e?JSON.stringify([e.parameters.without,e.parameters.priceYear,e.options.baseYear,e.options.rate,e.parameters.unit,e.rows.map(r=>r.year)]):null}
function scenarioRows(){const reference=scenario().economic??state.scenarios.find(s=>s.economic)?.economic,signature=economicSignature(reference);const current=filter(),date=$('#analysis-date').value,rows=[['変更しない（基準）',analysis?fmt(analysis.before.trips)+'便':'未算定','—','—','—','0万円']];for(const s of state.scenarios){const same=s.supply&&s.supply.date===date&&JSON.stringify(s.supply.filter)===JSON.stringify(current),a=s.reach?.result,reachSame=s.reach?.date===date&&reach&&JSON.stringify(s.reach.options)===JSON.stringify(reach.after.options),e=s.economic,equalEconomic=!e||!signature||economicSignature(e)===signature;rows.push([esc(s.name),same?fmt(s.supply.after.trips)+'便':'同じ条件で再集計が必要',a&&reachSame?`${Object.keys(a.after.best).length}乗り場 / 喪失${a.comparison.filter(r=>r.change==='到達不可').length}`:a?'起点・時刻等の条件を確認':'未算定',s.demand?.result?.available?`${fmt(s.demand.result.low)}〜${fmt(s.demand.result.high)}回`:'未算定',e?(!equalEconomic?'比較条件が不一致':e.stale?'要再確認':fmt(e.result.bc,2)):'未算定',e?(!equalEconomic?'比較条件が不一致':e.stale?'要再確認':money(e.result.npv)):'未算定'])}return rows}
function renderComparison(){if(!$('#scenario-comparison'))return;$('#scenario-comparison').innerHTML=`<div class="panel"><div class="panel-title"><h2>基準と3つの変更案</h2><button id="compare-all" class="button">3案の供給を同じ条件で集計</button></div><p class="meta">運行条件：${esc($('#analysis-date').value)} · ${esc($('#route-select').selectedOptions[0]?.textContent??'')} · ${esc($('#time-window').selectedOptions[0]?.textContent??'')}。</p>${table(['案','該当時間帯の便数','到達先 / 喪失','需要の仮定範囲','部分B/C','純便益 NPV'],scenarioRows())}<p class="meta">費用便益は各案で入力した同じ将来の現状維持案・価格年・期間に揃えて比較してください。B/Cの大小だけで自動順位付けしません。未実施の現地検証を成果として記載しません。</p></div>`;on('#compare-all','click',compareAll)}
async function compareAll(){if(!state.feeds.length)throw Error('GTFSを先に取り込んでください');const date=$('#analysis-date').value,scope=filter();for(const s of state.scenarios){message(s.name+'を同じ条件で集計しています…',true);const r=await request('prepare',{feeds:state.feeds,edits:s.edits,date,filter:scope});s.supply={date,filter:scope,before:r.before,after:r.after}}await request('prepare',{feeds:state.feeds,edits:scenario().edits,date,filter:scope});renderComparison();message('3案の供給を同じ分析日・路線・方向・時間帯で集計しました。')}
function captureProject(){state.name=$('#project-name').value.trim()||'交通改善計画';state.engine=ENGINE_VERSION;state.savedAt=new Date().toISOString();scenario().economicDraft=Object.fromEntries(new FormData($('#econ-form')));state.drafts={forecastInput:$('#forecast-input').value,forecastSource:$('#forecast-source').value,forecastFrequency:$('#forecast-frequency').value,forecastHorizon:$('#forecast-horizon').value,observationMeta:observationMeta()};state.view={date:$('#analysis-date').value,filter:filter()};state.decision=Object.fromEntries(new FormData($('#decision-form')));return state}
function saveProject(){const data=captureProject();download('oita-transport-project.json',JSON.stringify(data),'application/json');message('再計算用の計画ファイルを保存しました。読み込んだ集計データも含まれます。')}
async function loadProject(file){if(file.size>100*1024*1024)throw Error('計画ファイルは100MB以内に分けてください');const p=JSON.parse(await file.text());if(p.schema!=='oita-planning-project/1'||!Array.isArray(p.feeds)||!Array.isArray(p.scenarios)||p.scenarios.length!==3||!p.scenarios.every(s=>typeof s.name==='string'&&Array.isArray(s.edits))||!p.scenarios.some(s=>s.id===p.selected))throw Error('対応する計画ファイルではありません');const q=validateFeeds(p.feeds);if(q.errors)throw Error('計画内のGTFSが検証を通過しません');state=p;for(const s of state.scenarios){delete s.supply;delete s.reach;if(s.demand?.options)s.demand.result=demandSensitivity(s.demand.options)}changed=[];$('#project-name').value=state.name;$('#analysis-date').value=p.view?.date??'2026-09-08';renderScenarioSelect();for(const [name,value]of Object.entries(p.decision??{}))if($('#decision-form').elements.namedItem(name))$('#decision-form').elements.namedItem(name).value=value;
  await refresh({fit:true});if(p.view?.filter){$('#route-select').value=p.view.filter.route;$('#direction-select').value=p.view.filter.direction;$('#time-window').value=p.view.filter.start+','+p.view.filter.end;await refresh()}
  if(state.observations){rideResult=analyzeRidership(state.observations.rows,state.feeds,state.observations.meta);renderRideResult()}if(state.od){odResult=analyzeOD(state.od.rows,state.feeds,state.od.meta);renderODResult()}
  if(!state.observations){rideResult=null;$('#observed-results').innerHTML=empty('乗降データは未取込です。')}if(!state.od){odResult=null;$('#od-results').innerHTML=empty('OD集計は未取込です。')}
  if(state.forecast){$('#forecast-input').value=csvText(state.forecast.rows);$('#forecast-frequency').value=state.forecast.frequency;$('#forecast-horizon').value=state.forecast.horizon;$('#forecast-source').value=state.forecast.source;calculateForecast()}
  if(state.drafts){const d=state.drafts;if(d.forecastInput!==undefined)$('#forecast-input').value=d.forecastInput;if(d.forecastSource!==undefined)$('#forecast-source').value=d.forecastSource;const m=d.observationMeta??{};for(const [id,value]of Object.entries({'#obs-source':m.source,'#obs-from':m.from,'#obs-to':m.to,'#obs-scope':m.scope,'#obs-basis':m.basis,'#obs-complete':m.complete,'#obs-initial':m.initialEmpty,'#obs-final':m.finalEmpty,'#od-unit':m.unit}))if(value!==undefined)$(id).value=value}
  for(const s of state.scenarios)if(s.economic){s.economic.result=economics(s.economic.rows,s.economic.options);s.economic.sensitivities=economicSensitivity(s.economic.rows,s.economic.options);s.economic.switchPoint=switchingDemand(s.economic.rows,s.economic.options)}restoreEconomicForm();renderComparison();message('計画を読み込み、データから再計算しました。到達比較は再実行してください。')}
async function exportGTFS(){if(!analysis)throw Error('運行比較の再計算が完了してから出力してください');if(!changed.length)throw Error('GTFSを読み込んでください');const q=validateFeeds(changed);if(q.errors)throw Error('GTFSのエラーを解消してから出力してください');if(changed.length===1)download('scenario-gtfs.zip',exportFeed(changed[0]));else{const files={};for(const f of changed)files[f.id+'-gtfs.zip']=new Uint8Array(await exportFeed(f).arrayBuffer());files['README.txt']='各ZIPは独立したGTFSです。統合GTFSではありません。変更案の配車・勤務・運行可否は未確認。\n'+changed.map(f=>f.id+' '+f.name+' '+f.source).join('\n');download('scenario-gtfs-bundle.zip',zip(files))}message('変更案のGTFSを保存しました。運行に使う前の事業者確認が必要です。')}
function exportResults(){if(!analysis)throw Error('運行比較の再計算が完了してから出力してください');const files={'stop-supply-change.csv':'\uFEFF'+csvText(stopDiff(),{safe:true}),'gtfs-edit-ledger.csv':'\uFEFF'+csvText(scenario().edits.map((e,i)=>({order:i+1,type:e.type,feed:e.feed,trip:e.trip??'',change:JSON.stringify(e)})),{safe:true}),'quality-checks.csv':'\uFEFF'+csvText(validateFeeds(changed).issues,{safe:true})};if(reach)files['reach-change.csv']='\uFEFF'+csvText(reach.comparison,{safe:true});if(rideResult){files['ridership-matched.csv']='\uFEFF'+csvText(rideResult.matched,{safe:true});files['ridership-unmatched.csv']='\uFEFF'+csvText(rideResult.unmatched,{safe:true});files['onboard-by-segment.csv']='\uFEFF'+csvText(rideResult.loads.flatMap(g=>g.series.map(r=>({...r,load_state:g.state}))),{safe:true})}if(odResult){files['od-cells.csv']='\uFEFF'+csvText(odResult.cells,{safe:true});files['od-errors.csv']='\uFEFF'+csvText(odResult.errors,{safe:true})}if(forecastResult){files['forecast.csv']='\uFEFF'+csvText(forecastResult.future,{safe:true});files['forecast-backtests.csv']='\uFEFF'+csvText(forecastResult.folds,{safe:true})}if(scenario().economic){files['economic-cashflow.csv']='\uFEFF'+csvText(scenario().economic.result.cashflows,{safe:true});files['economic-sensitivity.csv']='\uFEFF'+csvText(scenario().economic.sensitivities,{safe:true})}files['analysis-conditions.json']=JSON.stringify({engine:ENGINE_VERSION,created:new Date().toISOString(),project:state.name,scenario:scenario().name,view:{date:$('#analysis-date').value,filter:filter()},usage:'https://mobilitydlab.com/oita-mobility/usage.html#sources',sources:state.feeds.map(f=>({id:f.id,name:f.name,hash:f.hash,source:f.source,catalog:f.catalog,license:f.license||'提供者の条件を確認',licenseUrl:f.licenseUrl||(f.license==='CC BY 4.0'?'https://creativecommons.org/licenses/by/4.0/deed.ja':''),attribution:f.attribution||f.name})),rideMeta:state.observations?.meta,odMeta:state.od?.meta,forecast:state.forecast?{source:state.forecast.source,frequency:state.forecast.frequency}:null,demand:scenario().demand,economic:scenario().economic?{parameters:scenario().economic.parameters,options:scenario().economic.options,stale:scenario().economic.stale}:null,decision:captureProject().decision},null,2);download('transport-analysis-tables.zip',zip(files));message('算定表と入力条件を保存しました。')}
function reportMap(){if(!analysis)return '';const stops=Object.values(analysis.stops);if(!stops.length)return '';const lats=stops.map(s=>s.lat),lons=stops.map(s=>s.lon),minLat=Math.min(...lats),maxLat=Math.max(...lats),minLon=Math.min(...lons),maxLon=Math.max(...lons),cos=Math.cos((minLat+maxLat)/2*Math.PI/180),spanX=Math.max(.001,(maxLon-minLon)*cos),spanY=Math.max(.001,maxLat-minLat),scale=Math.min(850/spanX,500/spanY),x=s=>35+((s.lon-minLon)*cos*scale)+(850-spanX*scale)/2,y=s=>35+((maxLat-s.lat)*scale)+(500-spanY*scale)/2,diffs=new Map(stopDiff().map(r=>[r.key,r]));return `<svg viewBox="0 0 920 570" role="img" aria-label="収録乗り場の緯度経度に基づく出発数の変化"><rect width="920" height="570" fill="#f0f5f8"/>${stops.map(s=>{const d=diffs.get(s.key)?.delta??0;return `<circle cx="${x(s).toFixed(2)}" cy="${y(s).toFixed(2)}" r="${d?4:2}" fill="${d>0?'#087e80':d<0?'#ba543c':'#7793ae'}"><title>${esc(s.name)}：${signed(d)}本</title></circle>`}).join('')}<text x="24" y="550" font-size="15" fill="#476572">緑：増便　赤：減便　青灰：変更なし　／　地理座標による乗り場配置・背景道路なし</text></svg>`}
function exportReport(){if(!analysis)throw Error('運行比較の再計算が完了してから出力してください');captureProject();const q=validateFeeds(changed),e=scenario().economic,decision=Object.entries(state.decision).map(([k,v])=>[esc(({problem:'移動の問題',owner:'判断責任者',decisionDate:'判断日',operator:'運行主体',payer:'費用負担・予算責任者',dataOwner:'データ責任者',measurementDate:'次の実測日',criteria:'継続・変更・中止条件',distribution:'不利益・代替案',learning:'実測と学習'})[k]??k),esc(v||'未設定・未実施')]);const html=`<!doctype html><html lang="ja"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(state.name)} 分析レポート</title><style>body{font:16px/1.8 -apple-system,BlinkMacSystemFont,"Yu Gothic",sans-serif;color:#173b50;max-width:1100px;margin:30px auto;padding:0 22px}h1{font-size:30px}h2{font-size:23px;border-bottom:2px solid #215ec7;padding-bottom:8px;margin-top:40px}p{margin:13px 0}table{border-collapse:collapse;width:100%;font-size:14px}th,td{text-align:left;padding:10px;border:1px solid #dae3e9;vertical-align:top}th{background:#edf3f8}small{display:block;color:#526b78}.table-wrap{overflow:auto;margin:20px 0}svg{width:100%;height:auto}a{color:#215ec7}.notice{padding:16px;background:#fff4df;border-left:4px solid #ba8631}.action-link{border:0;background:none;color:inherit;font:inherit;text-align:left}@media print{body{margin:10mm;max-width:none;padding:0}h2{break-after:avoid}tr{break-inside:avoid}.table-wrap{overflow:visible}table{font-size:11px}}</style><h1>${esc(state.name)}</h1><p>対象案：${esc(scenario().name)} · 出力日 ${new Date().toISOString().slice(0,10)} · 算定版 ${ENGINE_VERSION}</p><div class="notice">公開GTFSと取込集計・入力仮定による計画分析。配車・勤務・道路走行可否・現地効果・正式な事業採否は確認前です。未評価項目をゼロと確認したものではありません。</div><h2>比較条件と案</h2><p>運行日 ${esc($('#analysis-date').value)} ／ 路線 ${esc($('#route-select').selectedOptions[0]?.textContent)} ／ ${esc($('#time-window').selectedOptions[0]?.textContent)}</p>${table(['案','便数','到達先 / 喪失','需要仮定','部分B/C','NPV'],scenarioRows())}<h2>地図と供給変化</h2>${reportMap()}${table(['乗り場','基準出発','案の出発','増減','最終 基準','最終 案'],stopDiff().slice(0,100).map(r=>[esc(r.name),r.before,r.after,signed(r.delta),r.last0??'—',r.last1??'—']))}${reach?`<h2>到達比較</h2><p>起点 ${esc(analysis.stops[reach.after.options.origin]?.name)} ／ ${clock(reach.after.options.departure)}発 ／ ${reach.after.options.budget/60}分以内 ／ 乗換${reach.after.options.maxTransfers}回まで。徒歩は${reach.after.options.maxWalk}m以内の直線概算。</p>${table(['乗り場','基準 分','変更 分','変化'],reach.comparison.filter(r=>r.change!=='変化なし').slice(0,200).map(r=>[esc(r.name),fmt(r.before,1),fmt(r.after,1),r.change]))}`:'<h2>到達比較</h2><p>未算定</p>'}<h2>乗降・ODの根拠</h2>${rideResult?`<p>${esc(rideResult.meta.source)} ／ ${esc(rideResult.meta.from)}〜${esc(rideResult.meta.to)} ／ ${esc(rideResult.meta.scope)}。照合済み乗車${fmt(rideResult.boardings)}回、降車${fmt(rideResult.alightings)}回、対象${rideResult.observedTrips}便。不一致${rideResult.unmatched.length}行。</p>`:'<p>事業者の便別乗降実績は未取込。</p>'}${odResult?`<p>OD出典 ${esc(odResult.meta.source)} ／ ${esc(odResult.meta.from)}〜${esc(odResult.meta.to)}。提供観測セル合計${fmt(odResult.total)}回。非表示${odResult.suppressed}セル。欠測を0で補完していません。</p>`:'<p>OD集計は未取込。</p>'}<h2>需要の見通し</h2>${forecastResult?`<p>${esc(state.forecast.source)}。過去検証${forecastResult.folds.length}回、${forecastResult.sufficient?'MAE比較':'検証不足'}。施策の因果効果・予測区間は未推定。</p>${table(['期間','基準延長','傾向延長'],forecastResult.future.map(r=>[r.period,fmt(r.baseline,1),fmt(r.trend,1)]))}`:'<p>未算定</p>'}${scenario().demand?`<p>供給感度の入力：${esc(JSON.stringify(scenario().demand.options))}。係数は仮定で、大分での実証係数ではありません。</p>`:''}<h2>年別費用便益</h2>${e?`<p>${esc(e.parameters.without)}との比較。${esc(e.parameters.source)} ／ ${esc(e.parameters.priceYear)}年価格、割引率${e.options.rate*100}%。${e.stale?'変更案の更新後、条件再確認が必要。':''}</p><p>部分B/C ${fmt(e.result.bc,2)} ／ NPV ${money(e.result.npv)}。資源費用方式の部分B/C ${fmt(e.result.resourceBC,2)}。${e.result.externalUnassessed?'外部影響は一部または全期間未評価。':''}</p><p>利用者便益＝平均需要×一般化費用差（時間×時間価値＋運賃）。運営者便益＝増分運賃収入−増分運行資源費。便益に残存価値・評価した外部便益を加え、追加投資・更新・撤去を費用として年別に割引。</p>${table(['年','基準 年間回数','案 年間回数','利用者便益','運営者便益','投資等費用','割引後純便益'],e.result.cashflows.map(r=>[r.year,fmt(r.q0),fmt(r.q1),money(r.userBenefit),money(r.providerBenefit),money(r.cost),money(r.npv)]))}${table(['感度条件','部分B/C','NPV'],e.sensitivities.map(r=>[r.name,fmt(r.bc,2),money(r.npv)]))}`:'<p>未算定。変更案の実費・対象人数・時間差・外部影響の入力が必要です。</p>'}<h2>判断・実行・学習</h2>${table(['項目','記録'],decision)}<h2>変更履歴</h2>${table(['順番','操作','対象','変更内容'],scenario().edits.map((r,i)=>[i+1,esc(r.type),esc(r.feed+' '+(r.trip??r.id??'')),esc(JSON.stringify(r.values??r.rows??{minutes:r.minutes}).slice(0,600))]))}<h2>データ出典・検証</h2>${table(['ID・出典','SHA-256','取得情報'],state.feeds.map(f=>[`${esc(f.id)} ${esc(f.name)}<br>${link(f.source,'原GTFS')}`,esc(f.hash),esc(f.retrieved||f.importedAt)]))}<p>主要項目の検証：エラー${q.errors}件、注意${q.warnings}件。完全なGTFS-JP v4適合認証ではありません。</p>${table(['データ','項目','内容'],q.issues.map(r=>[esc(r.feed),esc(r.code),esc(r.message)]))}<h2>算定の対応範囲</h2>${table(['機能','実装','範囲・未実施'],capabilities)}<p>参照：${link('https://gtfs.org/documentation/schedule/reference/','GTFS仕様')} ／ ${link('https://www.mlit.go.jp/tetudo/tetudo_fr1_000040.html','国交省評価マニュアル')} ／ ${link('https://otexts.com/fpp3/tscv.html','時系列交差検証')}。大分県公開GTFSはCC BY 4.0に基づき加工。集計データの再配布条件は提供者によります。</p></html>`;download('transport-planning-report.html',html,'text/html;charset=utf-8');message('地図・算定・根拠・判断条件を含むレポートを保存しました。')}

async function start(){
  renderScenarioSelect();setupMap();route();window.addEventListener('hashchange',route);
  on('#example-add','click',()=>{exampleAdded=true;renderExample();$('#example-result').scrollIntoView({block:'center',behavior:'smooth'})});on('#example-reset','click',()=>{exampleAdded=false;renderExample()});
  document.addEventListener('click',e=>{const a=e.target.closest('[data-jump]');if(a){e.preventDefault();document.getElementById(a.dataset.jump)?.scrollIntoView({block:'start',behavior:'smooth'})}});
  on('#recalculate','click',()=>refresh());on('#analysis-date','change',()=>refresh());on('#route-select','change',()=>refresh());on('#direction-select','change',()=>refresh());on('#time-window','change',()=>refresh());
  on('#scenario-select','change',async()=>{scenario().economicDraft=Object.fromEntries(new FormData($('#econ-form')));state.selected=$('#scenario-select').value;restoreEconomicForm();await refresh()});
  on('#rename-scenario','click',()=>{const name=window.prompt('変更案の名前',scenario().name);if(name?.trim()){scenario().name=name.trim().slice(0,100);renderScenarioSelect();renderComparison()}});
  on('#edit-feed','change',renderRoutes);on('#edit-route','change',renderTrips);on('#edit-trip','change',renderTripEditor);on('#edit-stop','change',renderStopEditor);
  on('#shift-trip','click',async()=>{await addEdit({type:'shift',feed:$('#edit-feed').value,trip:$('#edit-trip').value,minutes:num($('#shift-minutes').value,{negative:true})});invalidateScenario()});
  on('#duplicate-trip','click',async()=>{const trip=$('#edit-trip').value,newId=trip+'__plan_'+Date.now();await addEdit({type:'duplicate',feed:$('#edit-feed').value,trip,newId,minutes:num($('#shift-minutes').value,{negative:true})});invalidateScenario()});
  on('#cancel-trip','click',async()=>{await addEdit({type:'cancel',feed:$('#edit-feed').value,trip:$('#edit-trip').value});invalidateScenario()});
  on('#undo-edit','click',async()=>{scenario().edits.pop();invalidateScenario();await refresh()});
  on('#trip-editor','click',e=>{const b=e.target.closest('[data-delete-call]');if(b){const rows=editedCalls();rows.splice(Number(b.dataset.deleteCall),1);renderCalls(rows)}});
  on('#insert-call','click',()=>{const rows=editedCalls(),last=rows.at(-1)?.departure_time??'09:00:00';rows.push({stop_id:$('#insert-stop').value,arrival_time:last,departure_time:last,pickup_type:'0',drop_off_type:'0'});renderCalls(rows)});
  on('#save-calls','click',async()=>{const rows=editedCalls();if(rows.length<2)throw Error('1便に2つ以上の停車箇所が必要です');if(rows.some(r=>seconds(r.arrival_time)===null||seconds(r.departure_time)===null))throw Error('全停車箇所にHH:MM:SS形式の時刻を入力してください');await addEdit({type:'calls',feed:$('#edit-feed').value,trip:$('#edit-trip').value,rows});invalidateScenario()});
  on('#save-route-name','click',()=>addEdit({type:'route',feed:$('#edit-feed').value,id:$('#edit-route').value,values:{route_long_name:$('#edit-route-name').value}}));
  const stopValues=()=>({stop_name:$('#edit-stop-name').value.trim(),stop_lat:String(num($('#edit-lat').value,{negative:true})),stop_lon:String(num($('#edit-lon').value,{negative:true}))});
  on('#save-stop','click',async()=>{await addEdit({type:'stop',feed:$('#edit-feed').value,id:$('#edit-stop').value,values:stopValues()});invalidateScenario()});
  on('#add-stop','click',async()=>{await addEdit({type:'new_stop',feed:$('#edit-feed').value,values:{stop_id:'plan_stop_'+Date.now(),...stopValues()}});invalidateScenario()});
  on('#calculate-reach','click',calculateReach);on('#fit-map','click',fitMap);
  for(const [id,mode]of [['#map-supply','supply'],['#map-access','access'],['#map-riders','riders'],['#map-od','od']])on(id,'click',()=>{if(mode==='access'&&!reach){location.hash='access';$('#reach-origin').focus();return;}if(mode==='riders'&&!rideResult)throw Error('乗降集計を先に取り込んでください');if(mode==='od'&&!odResult)throw Error('OD集計を先に取り込んでください');mapMode=mode;drawMap()});
  document.addEventListener('click',e=>{const b=e.target.closest('[data-focus-stop]'),o=e.target.closest('[data-origin]');if(b){const s=analysis?.stops[b.dataset.focusStop];if(s){location.hash='design';map.setView([s.lat,s.lon],15);$('#lab-map').scrollIntoView({block:'center',behavior:'smooth'})}}if(o){$('#reach-origin').value=o.dataset.origin;$('#reach-origin').scrollIntoView({block:'center',behavior:'smooth'})}});
  on('#replace-seed','click',()=>loadSeed(true));on('#append-seed','click',()=>loadSeed(false));on('#gtfs-files','change',async e=>{for(const file of e.target.files)await acceptFeed(await file.arrayBuffer(),file.name,false)});
  on('#project-file','change',e=>e.target.files[0]?loadProject(e.target.files[0]):null);on('#observed-file','change',loadObservedFile);on('#csv-encoding','change',loadObservedFile);on('#import-kind','change',renderMapping);on('#apply-observed','click',runObserved);on('#download-observed-template','click',observedTemplate);
  on('#calculate-forecast','click',calculateForecast);on('#load-hita','click',()=>{$('#forecast-frequency').value='annual';$('#forecast-horizon').value='3';$('#forecast-input').value='period,value\n2021,71075\n2022,68469\n2023,79443\n2024,84189\n2025,85402';$('#forecast-source').value='日田市・ひたはしり号・バス年度（前年10月〜当年9月）。https://www.city.hita.oita.jp/uploaded/attachment/9067.pdf 。2026年10月改正の影響は未反映。';calculateForecast()});on('#calculate-demand','click',calculateDemand);
  on('#use-supply','click',()=>{if(!analysis)throw Error('運行比較が未算定です');if($('#route-select').value==='all')throw Error('地図画面で対象の1路線を選んでください');$('#demand-f0').value=analysis.before.trips;$('#demand-f1').value=analysis.after.trips;message('選択した路線・方向・時間帯の便数を転記しました。年間人数の対象範囲を合わせてください。')});
  on('#econ-form','submit',e=>{e.preventDefault();calculateEconomics()});on('#econ-form','input',()=>{if(scenario().economic){scenario().economic.stale=true;renderEconomics();renderComparison()}message('費用便益の条件が変わりました。計算ボタンで結果を更新してください。')});on('#econ-example','click',exampleEconomics);
  on('#cashflow-template','click',()=>{const rows=scenario().economic?.rows??[2026,2027].map(year=>({year,q0:'',q1:'',time0:'',time1:'',fare0:'',fare1:'',opex0:'',opex1:'',capital:'',replacement:'',decommission:'',residual:'',external:''}));download('annual-cashflow-template.csv','\uFEFF'+csvText(rows,{safe:true}),'text/csv;charset=utf-8')});
  on('#cashflow-file','change',async e=>{const file=e.target.files[0];if(!file)return;cashflowImport=parseCSV(await file.text());$('#calculate-cashflow').disabled=!cashflowImport.length;$('#cashflow-state').textContent=file.name+' · '+cashflowImport.length+'年分。必須数値は計算時に検査します。'});on('#calculate-cashflow','click',()=>{if(!cashflowImport?.length)throw Error('年別CSVを選んでください');calculateEconomics(cashflowImport)});
  on('#decision-form','submit',e=>{e.preventDefault();state.decision=Object.fromEntries(new FormData(e.target));message('判断条件をこの計画に記録しました。計画保存でファイルとして残せます。')});
  on('#save-project','click',saveProject);on('#save-project-2','click',saveProject);on('#export-report','click',exportReport);on('#export-results','click',exportResults);on('#export-gtfs','click',exportGTFS);
  const response=await fetch('data/gtfs/catalog.json');if(!response.ok)throw Error('公開データ一覧を読み込めません');catalog=await response.json();$('#seed-select').innerHTML=catalog.map(c=>opt(c.file,c.name)).join('');$('#seed-select').value=catalog.find(c=>c.file.includes('kusukanko'))?.file??catalog[0].file;await loadSeed(true);exampleFeed=structuredClone(state.feeds[0]);renderExample();calculateForecast();message('玖珠観光バスの公開時刻表で操作できます。別の地域は「データを用意」から選べます。');
}
guarded(start);
